def sort(a: Vector[Int])(implicit ec: ExecutionContext): Future[Vector[Int]] =
  if (a.size < 1024) Future.successful(a.sorted)          // base case
  else {
    val (lo, hi) = a.splitAt(a.size / 2)
    for (l <- sort(lo); r <- sort(hi)) yield merge(l, r)   // fork + join + combine
  }
